// Agenda <-> Gestão: decide o que criar e reagendar. Nunca apaga nada, nunca conclui tarefa, nunca troca responsável.
// Regra: tarefa do gestão com horário é compromisso. Evento aceito na agenda vira tarefa. Tarefa com horário vira evento.
const TZ = 'America/Sao_Paulo';
const CAL = 'contato@euforiadigital.com';
const JANELA_DIAS = 14;
const CARENCIA_MIN = 30; // tarefa nova espera 30 min antes de virar evento (dá tempo de marcar o convite à mão)

// Gente da casa sem cadastro no gestão: não conta como convidado externo
const INTERNOS = ['cs.euforiadigital@gmail.com', 'rapha@jatobapassos.com', 'rafinhadutg@gmail.com'];
// Palavras que não servem para dizer que dois nomes são o mesmo compromisso
const STOP = new Set(['para', 'com', 'dos', 'das', 'the', 'and', 'uma', 'por', 'sem', 'reuniao', 'encontro', 'call', 'euforia', 'arco', 'gestao']);

const agora = Date.now();
const fim = agora + JANELA_DIAS * 864e5;

const norm = s => (s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const chave = s => norm(s).replace(/[^a-z0-9]+/g, ' ').trim();
const palavras = s => new Set(chave(s).split(' ').filter(w => w.length >= 3 && !STOP.has(w)));
const compartilha = (a, b) => { if (chave(a) === chave(b)) return true; const A = palavras(a); for (const w of palavras(b)) if (A.has(w)) return true; return false; };
const minuto = ms => Math.floor(ms / 60000);
const dia = ms => DateTime.fromMillis(ms, { zone: TZ }).toFormat('yyyy-LL-dd');
const hora = ms => DateTime.fromMillis(ms, { zone: TZ }).toFormat('HH:mm');
const fmt = ms => DateTime.fromMillis(ms, { zone: TZ }).toFormat('dd/LL HH:mm');
// Só vira reunião (com link do Meet) o compromisso cujo título diz que é. O resto entra na agenda sem Meet.
const ehReuniao = titulo => /\b(reuniao|call|alinhamento|encontro|diagnostico|weekly|meet)\b/.test(norm(titulo));
const idEvento = tarefaId => 'gt' + String(tarefaId).replace(/-/g, ''); // o Google só aceita 0-9 e a-v em id de evento; g, t e os hex do uuid cabem

const lido = $('Ler gestão').first().json.r || {};
const tarefas = lido.tarefas || [];
const emailsEquipe = new Set((lido.equipe || []).map(p => String(p.email).toLowerCase()));
const eventos = [];
for (const it of $('Ler agenda').all()) for (const e of (it.json.items || [])) eventos.push(e);
const tarefaPorId = new Map(tarefas.map(t => [t.id, t]));

const inicioEv = e => (e.start && e.start.dateTime) ? Date.parse(e.start.dateTime) : null;
const fimEv = e => (e.end && e.end.dateTime) ? Date.parse(e.end.dateTime) : null;
const aceitoOuNosso = e => {
  const org = ((e.organizer && e.organizer.email) || '').toLowerCase();
  if (org === CAL) return true;
  const eu = (e.attendees || []).find(a => a.self || (a.email || '').toLowerCase() === CAL);
  return !!(eu && eu.responseStatus === 'accepted');
};
const eventoValido = e => e.status !== 'cancelled' && inicioEv(e) !== null && e.transparency !== 'transparent' && aceitoOuNosso(e);
const eventoConta = e => eventoValido(e) && inicioEv(e) >= agora && inicioEv(e) <= fim;
const doGestao = e => /^gt[0-9a-f]{32}$/.test(e.id || '') || /Criado automaticamente a partir do gestão/.test(e.description || '');
const marcasTarefa = e => {
  const s = new Set();
  for (const m of (e.description || '').matchAll(/Gestão EuforIA \(tarefa ([0-9a-f-]{36})\)/g)) s.add(m[1]);
  const m = /^gt([0-9a-f]{8})([0-9a-f]{4})([0-9a-f]{4})([0-9a-f]{4})([0-9a-f]{12})$/.exec(e.id || '');
  if (m) s.add(m.slice(1).join('-'));
  return s;
};
const dueMs = t => (t.prazo && t.horario) ? DateTime.fromISO(`${t.prazo}T${t.horario}`, { zone: TZ }).toMillis() : null;
const pessoal = t => { const n = norm(t.titulo); return n.includes('[pessoal]') || n.includes('[psi]'); };
const tarefaConta = t => {
  if (t.concluida || t.agenda_evento_id || pessoal(t)) return false;
  const d = dueMs(t);
  return !!d && d >= agora && d <= fim;
};
const primeiroNome = a => {
  let base = (a.nome || '').trim().split(/\s+/)[0];
  if (!base) base = a.email.split('@')[0].split(/[._\-0-9]+/).filter(Boolean)[0] || a.email;
  return base.charAt(0).toUpperCase() + base.slice(1);
};

const acoes = [];
const duvidas = [];

// Passo 1: Agenda -> Gestão
const novas = []; // criadas nesta rodada, para não duplicar
let eventosContam = 0;
for (const e of eventos) {
  if (!eventoConta(e)) continue;
  eventosContam++;
  if (doGestao(e)) continue; // evento que nasceu de tarefa do gestão nunca volta para o gestão
  const convidados = (e.attendees || [])
    .map(a => ({ email: (a.email || '').toLowerCase(), nome: a.displayName || '' }))
    .filter(a => a.email && a.email !== CAL && !a.email.endsWith('@resource.calendar.google.com'));
  const daEquipe = convidados.filter(a => emailsEquipe.has(a.email)).map(a => a.email);
  const externos = convidados.filter(a => !emailsEquipe.has(a.email) && !INTERNOS.includes(a.email) && !a.email.endsWith('@euforiadigital.com'));

  let nome = (e.summary || '(sem título)').replace(/\s+/g, ' ').trim();
  if (!nome.startsWith('[') && externos.length) nome = `[${primeiroNome(externos[0])}] ${nome}`;
  const ini = inicioEv(e);

  let par = false, duvida = false;
  for (const t of [...tarefas, ...novas]) {
    if (t.agenda_evento_id === e.id) { par = true; break; }
    const d = dueMs(t) || (t.prazo ? DateTime.fromISO(t.prazo, { zone: TZ }).toMillis() : null);
    if (!d) continue;
    if (t.horario) {
      if (dia(d) === dia(ini) && chave(t.titulo) === chave(nome)) { par = true; break; }
      if (dia(d) === dia(ini) && chave(t.titulo) === chave(e.summary)) { par = true; break; }
      if (minuto(d) !== minuto(ini)) continue;
      if (compartilha(e.summary, t.titulo)) { par = true; break; }
      duvida = true;
    } else if (dia(d) === dia(ini) && chave(t.titulo) === chave(e.summary)) { par = true; break; }
  }
  if (par) continue;
  if (duvida) { duvidas.push(`Evento "${nome}" (${fmt(ini)}): já existe tarefa nesse horário com outro nome. Não criei.`); continue; }

  const video = ((e.conferenceData && e.conferenceData.entryPoints) || []).find(p => p.entryPointType === 'video');
  const meet = e.hangoutLink || (video && video.uri);
  const notas = [`Agenda: ${e.htmlLink}`, meet ? `Meet: ${meet}` : null, 'Criada automaticamente a partir da agenda.'].filter(Boolean).join('\n\n');
  novas.push({ id: null, titulo: nome, prazo: dia(ini), horario: hora(ini), agenda_evento_id: e.id });
  acoes.push({ tipo: 'criar_tarefa', rotulo: `${nome} · ${fmt(ini)}`, titulo: nome, prazo: dia(ini), horario: hora(ini), emails: JSON.stringify(daEquipe), evento_id: e.id, notas });
}

// Passo 2: tarefa que nasceu da agenda segue a agenda (remarcação e cancelamento)
const evPorId = new Map(eventos.map(e => [e.id, e]));
for (const t of tarefas) {
  if (t.concluida || !t.agenda_evento_id) continue;
  const e = evPorId.get(t.agenda_evento_id);
  if (!e) continue; // evento fora da janela lida: não mexe
  if (e.status === 'cancelled') {
    if (!t.titulo.startsWith('[Cancelada na agenda]')) acoes.push({ tipo: 'atualizar_tarefa', rotulo: `cancelada: ${t.titulo}`, tarefa_id: t.id, prazo: '', horario: '', titulo: `[Cancelada na agenda] ${t.titulo}` });
    continue;
  }
  const ini = inicioEv(e);
  if (ini === null) continue;
  const d = dueMs(t);
  if (d === null || minuto(ini) !== minuto(d)) {
    acoes.push({ tipo: 'atualizar_tarefa', rotulo: `${t.titulo}: ${d ? fmt(d) : 'sem horário'} → ${fmt(ini)}`, tarefa_id: t.id, prazo: dia(ini), horario: hora(ini), titulo: '' });
  }
}

// Passo 2b: evento que nasceu do gestão segue a tarefa (remarcação feita no gestão)
const movidas = new Set();
for (const e of eventos) {
  if (e.status === 'cancelled' || !doGestao(e)) continue;
  const ini = inicioEv(e), fimE = fimEv(e);
  if (ini === null) continue;
  const t = [...marcasTarefa(e)].map(id => tarefaPorId.get(id)).find(Boolean);
  if (!t || movidas.has(t.id) || t.concluida || pessoal(t)) continue;
  const d = dueMs(t);
  if (!d || d < agora) continue;
  if (minuto(d) === minuto(ini)) continue;
  movidas.add(t.id);
  const dur = (fimE && fimE > ini) ? fimE - ini : 3600000;
  const novoIni = DateTime.fromMillis(d, { zone: TZ });
  acoes.push({
    tipo: 'atualizar_evento', event_id: e.id, rotulo: `${t.titulo}: ${fmt(ini)} → ${fmt(d)}`,
    corpo: {
      start: { dateTime: novoIni.toISO({ suppressMilliseconds: true }), timeZone: TZ },
      end: { dateTime: novoIni.plus({ milliseconds: dur }).toISO({ suppressMilliseconds: true }), timeZone: TZ },
    },
  });
}

// Passo 3: Gestão -> Agenda (tarefas iguais no mesmo horário viram UM evento)
const grupos = new Map();
for (const t of tarefas) {
  if (!tarefaConta(t)) continue;
  if (t.criado_em && (agora - Date.parse(t.criado_em)) < CARENCIA_MIN * 60000) continue; // ainda na carência
  const k = `${minuto(dueMs(t))}|${chave(t.titulo)}`;
  if (!grupos.has(k)) grupos.set(k, []);
  grupos.get(k).push(t);
}
for (const grupo of grupos.values()) {
  grupo.sort((a, b) => (a.id < b.id ? -1 : 1));
  const t0 = grupo[0];
  const ids = new Set(grupo.map(t => t.id));
  const fixo = idEvento(t0.id);
  const d = dueMs(t0);
  let par = false, duvida = false;
  for (const e of eventos) {
    const ligado = e.id === fixo || [...marcasTarefa(e)].some(id => ids.has(id));
    if (e.status === 'cancelled') { if (ligado) { par = true; break; } continue; } // apagado na agenda: respeita, não recria
    if (ligado) { par = true; break; }
    const ini = inicioEv(e);
    if (ini === null) continue;
    if (dia(ini) === dia(d) && chave(e.summary) === chave(t0.titulo)) { par = true; break; }
    if (minuto(ini) !== minuto(d)) continue;
    if (compartilha(e.summary, t0.titulo)) { par = true; break; }
    if (eventoValido(e)) duvida = true;
  }
  if (par) continue;
  if (duvida) { duvidas.push(`Tarefa "${t0.titulo}" (${fmt(d)}): já existe evento nesse horário com outro nome. Não criei.`); continue; }
  const emails = [...new Set(grupo.map(t => (t.responsavel_emails || [])[0]).filter(Boolean))];
  const inicio = DateTime.fromMillis(d, { zone: TZ });
  acoes.push({
    tipo: 'criar_evento', rotulo: `${t0.titulo} · ${fmt(d)}${grupo.length > 1 ? ` (${grupo.length} tarefas, 1 evento)` : ''}`,
    corpo: {
      id: fixo,
      summary: t0.titulo,
      start: { dateTime: inicio.toISO({ suppressMilliseconds: true }), timeZone: TZ },
      end: { dateTime: inicio.plus({ hours: 1 }).toISO({ suppressMilliseconds: true }), timeZone: TZ },
      attendees: emails.map(email => ({ email })),
      description: `${grupo.map(t => `Gestão EuforIA (tarefa ${t.id})`).join('\n')}\n\nCriado automaticamente a partir do gestão.`,
      ...(ehReuniao(t0.titulo) ? { conferenceData: { createRequest: { requestId: `gt-${t0.id}-${minuto(d)}`, conferenceSolutionKey: { type: 'hangoutsMeet' } } } } : {}),
    },
  });
}

const resumo = {
  tipo: 'resumo',
  eventos_lidos: eventos.length,
  eventos_que_contam: eventosContam,
  tarefas_lidas: tarefas.length,
  tarefas_a_criar: acoes.filter(a => a.tipo === 'criar_tarefa').map(a => a.rotulo),
  eventos_a_criar: acoes.filter(a => a.tipo === 'criar_evento').map(a => a.rotulo),
  tarefas_reagendadas: acoes.filter(a => a.tipo === 'atualizar_tarefa').map(a => a.rotulo),
  eventos_reagendados: acoes.filter(a => a.tipo === 'atualizar_evento').map(a => a.rotulo),
  duvidas,
};

return [...acoes, resumo].map(json => ({ json }));
